/**
 * Mini schemastery value surface for the NodeWorkerJsHost overlay.
 *
 * The real @deepseek-ai/schemastery is an ESM build with a large surface; the
 * system-prompt overlay only value-imports the `z` root and constructs its
 * Config schema from `z.object`/`z.boolean`/`z.string`/`z.array` with chained
 * `.default()`. This overlay supplies exactly that surface (plus `.parse` that
 * fills defaults and a `.merge` for the cordis-shim Service.resolveConfig
 * path), so a faithful parse of the Config shape behaves like schemastery for
 * the fields the bridge actually hands over.
 *
 * @module @deepseek-ai/schemastery
 */

function baseSchema() {
  const s = { _default: undefined, __schemastery: true }
  s.default = (v) => { s._default = v; return s }
  s.optional = () => s
  s.required = () => s
  // Chained numeric constraints used by schema builders (e.g. the agent-loop
  // `z.number().step(1).min(1)`): this overlay constructs schemas faithfully;
  // validation is not applied on this host (config is validated manually).
  s.step = () => s
  s.min = () => s
  s.max = () => s
  s.parse = (v) => {
    if (s._default !== undefined && (v === undefined || v === null)) return s._default
    return v
  }
  return s
}

const z = {
  object(shape) {
    const s = baseSchema()
    s._shape = shape
    s.strict = () => s
    s.parse = (v) => {
      if (s._default !== undefined && (v === undefined || v === null)) return s._default
      const input = v == null ? {} : v
      const out = {}
      for (const [k, sub] of Object.entries(shape)) out[k] = sub.parse(input[k])
      return out
    }
    s.merge = (...schemas) => {
      const merged = {}
      for (const schema of [s, ...schemas]) {
        if (schema && schema._shape) Object.assign(merged, schema._shape)
      }
      return z.object(merged)
    }
    return s
  },
  array(item) {
    const s = baseSchema()
    s._item = item
    s.parse = (v) => {
      if (s._default !== undefined && (v === undefined || v === null)) return s._default
      if (v == null) return undefined
      return v.map((x) => item.parse(x))
    }
    return s
  },
  boolean() { return baseSchema() },
  number() { return baseSchema() },
  string() { return baseSchema() },
}

export default z
